-- Actualizacion integral de enemigos de las zonas 79 a 100
-- Actualiza name, image_url y description. Conserva IDs, estadisticas, niveles y recompensas.
-- El directorio actual de image_url se conserva; solo cambia el nombre del archivo .png.

BEGIN;

DO $$
DECLARE zona integer; total integer; bosses integer;
BEGIN
  FOR zona IN 79..100 LOOP
    SELECT COUNT(*), COUNT(*) FILTER (WHERE is_boss IS TRUE)
      INTO total, bosses FROM public.enemies WHERE zone_id = zona;
    IF total <> 6 THEN RAISE EXCEPTION 'Zona %: se esperaban 6 enemigos, existen %', zona, total; END IF;
    IF bosses <> 1 THEN RAISE EXCEPTION 'Zona %: se esperaba 1 boss, existen %', zona, bosses; END IF;
  END LOOP;
END $$;

CREATE TEMP TABLE tmp_enemy_replacements (
  zone_id integer NOT NULL,
  slot integer NOT NULL,
  new_name varchar(100) NOT NULL,
  new_slug varchar(255) NOT NULL,
  new_description text NOT NULL,
  PRIMARY KEY (zone_id, slot)
) ON COMMIT DROP;


DO $$
DECLARE conflict_count integer;
BEGIN
  SELECT COUNT(*) INTO conflict_count
  FROM tmp_enemy_replacements r
  JOIN public.enemies e ON LOWER(BTRIM(e.name)) = LOWER(BTRIM(r.new_name))
  WHERE e.zone_id NOT BETWEEN 79 AND 100;
  IF conflict_count > 0 THEN
    RAISE EXCEPTION 'Uno o mas nombres nuevos ya existen fuera de las zonas 79-100';
  END IF;
END $$;

WITH ranked_enemies AS (
  SELECT e.id, e.zone_id,
         ROW_NUMBER() OVER (
           PARTITION BY e.zone_id
           ORDER BY CASE WHEN e.is_boss IS TRUE THEN 1 ELSE 0 END, e.id
         ) AS slot
  FROM public.enemies e
  WHERE e.zone_id BETWEEN 79 AND 100
), updated AS (
  UPDATE public.enemies e
     SET name = r.new_name,
         image_url = CASE
           WHEN COALESCE(BTRIM(e.image_url), '') = '' THEN r.new_slug || '.png'
           WHEN POSITION('/' IN e.image_url) > 0 THEN REGEXP_REPLACE(e.image_url, '[^/]+$', r.new_slug || '.png')
           ELSE r.new_slug || '.png'
         END,
         description = r.new_description
  FROM ranked_enemies re
  JOIN tmp_enemy_replacements r ON r.zone_id = re.zone_id AND r.slot = re.slot
  WHERE e.id = re.id
  RETURNING e.id, e.zone_id, e.name, e.image_url, e.description, e.is_boss
)
SELECT * FROM updated ORDER BY zone_id, is_boss, id;

DO $$
DECLARE duplicated_names integer; duplicated_urls integer;
BEGIN
  SELECT COUNT(*) INTO duplicated_names FROM (
    SELECT LOWER(BTRIM(name)) FROM public.enemies WHERE zone_id BETWEEN 79 AND 100
    GROUP BY LOWER(BTRIM(name)) HAVING COUNT(*) > 1
  ) d;
  SELECT COUNT(*) INTO duplicated_urls FROM (
    SELECT LOWER(BTRIM(image_url)) FROM public.enemies WHERE zone_id BETWEEN 79 AND 100
    GROUP BY LOWER(BTRIM(image_url)) HAVING COUNT(*) > 1
  ) d;
  IF duplicated_names > 0 OR duplicated_urls > 0 THEN
    RAISE EXCEPTION 'Persisten duplicados: nombres=%, image_url=%', duplicated_names, duplicated_urls;
  END IF;
END $$;

COMMIT;

SELECT id, zone_id, name, image_url, description, is_boss
FROM public.enemies
WHERE zone_id BETWEEN 79 AND 100
ORDER BY zone_id, is_boss, id;
